package com.jumblemint.cows.data.database

import android.content.Context
import androidx.room.Database
import androidx.room.Room
import androidx.room.RoomDatabase
import androidx.room.TypeConverters // Keep this import
import androidx.room.migration.Migration
import androidx.sqlite.db.SupportSQLiteDatabase
import com.jumblemint.cows.data.dao.*
import com.jumblemint.cows.data.model.* // Reverted to wildcard import

@Database(
    entities = [Cow::class, Pasture::class, Activity::class, Settings::class, Note::class],
    version = 3,
    exportSchema = false
)
@TypeConverters(Converters::class)
abstract class CattleDatabase : RoomDatabase() {

    abstract fun cowDao(): CowDao
    abstract fun pastureDao(): PastureDao
    abstract fun activityDao(): ActivityDao
    abstract fun settingsDao(): SettingsDao
    abstract fun noteDao(): NoteDao

    companion object {
        @Volatile
        private var INSTANCE: CattleDatabase? = null

        val MIGRATION_1_2 = object : Migration(1, 2) {
            override fun migrate(db: SupportSQLiteDatabase) {
                db.execSQL("ALTER TABLE cows ADD COLUMN isWatched INTEGER NOT NULL DEFAULT 0")
                db.execSQL("CREATE TABLE IF NOT EXISTS `notes` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `title` TEXT NOT NULL DEFAULT '', `text` TEXT NOT NULL, `timestamp` INTEGER NOT NULL)")
            }
        }

        val MIGRATION_2_3 = object : Migration(2, 3) {
            override fun migrate(db: SupportSQLiteDatabase) {
                // Add photos column to cows to store comma-separated file paths
                db.execSQL("ALTER TABLE cows ADD COLUMN photos TEXT NOT NULL DEFAULT ''")
            }
        }

        fun getDatabase(context: Context, applicationContext: Context = context.applicationContext): CattleDatabase {
            return INSTANCE ?: synchronized(this) {
                val instance = Room.databaseBuilder(
                    applicationContext,
                    CattleDatabase::class.java,
                    "cattle_database"
                )
                    .addMigrations(MIGRATION_1_2, MIGRATION_2_3)
                    // Using fully qualified name for DatabaseCallback
                    .addCallback(com.jumblemint.cows.data.database.DatabaseCallback(context))
                    .build()
                INSTANCE = instance
                instance
            }
        }
    }
}

