import androidx.compose.ui.semantics.semantics
import androidx.compose.ui.semantics.testTag
import androidx.compose.ui.unit.dp

/**
 * Generic swipe-to-delete container with red background and trash icon.
 * Calls onDelete when fully dismissed in either direction.
 */
@OptIn(ExperimentalMaterialApi::class)
@Composable
fun <T> SwipeToDeleteContainer(
    item: T,
    modifier: Modifier = Modifier,
    enabled: Boolean = true,
    onDelete: (T) -> Unit,
    content: @Composable () -> Unit
) {
    val dismissState = rememberDismissState(
        confirmStateChange = { value ->
            if (value == DismissValue.DismissedToStart || value == DismissValue.DismissedToEnd) {
                onDelete(item)
                true
            } else {
                true
            }
        }
    )

    val scale by animateFloatAsState(
        targetValue = if (dismissState.targetValue == DismissValue.Default) 0.8f else 1.2f,
        label = "icon-scale"
    )

    SwipeToDismiss(
        state = dismissState,
        directions = if (enabled) setOf(DismissDirection.StartToEnd, DismissDirection.EndToStart) else emptySet(),
        background = {
            val color = MaterialTheme.colorScheme.error
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .background(color)
                    .semantics { testTag = "swipe_delete_bg" },
                contentAlignment = Alignment.Center
            ) {
                // Use your app's delete icon resource
                Icon(
                    imageVector = Icons.Filled.Delete,
                    contentDescription = null,
                    tint = Color.White,
                    modifier = Modifier.scale(scale)
                )
            }
        },
        dismissContent = {
            Box(modifier = modifier.padding(vertical = 2.dp)) {
                content()
            }
        }
    )
}

